import{_ as a}from"./chunks/architecture.DdIdPF_l.js";import{_ as t,o as i,c as s,a5 as o}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"アプリケーションとサービスの構造","description":"","frontmatter":{"title":"アプリケーションとサービスの構造","docId":"developer.architecture","translationKey":"developer.architecture","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","translationRevision":"bb70d9dc69b44676148b2d1234fb9c39c700f8e62dc8587afc7bcf151e23f538","order":30},"headers":[],"relativePath":"ja/developer/architecture.md","filePath":"ja/developer/architecture.md","lastUpdated":1794611623000}'),r={name:"ja/developer/architecture.md"};function c(d,e,l,n,p,h){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="application-and-service-architecture" tabindex="-1">アプリケーションとサービスの構造 <a class="header-anchor" href="#application-and-service-architecture" aria-label="Permalink to &quot;アプリケーションとサービスの構造 {#application-and-service-architecture}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>状態を所有するサービスに変更を配置します。<a href="./setup.html">セットアップ</a> を読み、既存ホストと明示的な単独ホストの違いを理解します。デスクトップは <code>AppCore</code> を1つ作り、1つの <code>ControlApi</code> で包み、そのインスタンスを WebView、ローカル CLI、エージェントに公開します。</p><h2 id="trace-an-operation" tabindex="-1">操作の経路を追う <a class="header-anchor" href="#trace-an-operation" aria-label="Permalink to &quot;操作の経路を追う {#trace-an-operation}&quot;">​</a></h2><ol><li><code>crates/tiktools-control-api/src/modules/</code> でメソッド登録を探します。登録はスキーマ、方針、検出メタデータを提供します。</li><li>ハンドラーから <code>crates/tiktools-core/src/control/</code> と担当サービスへ進みます。ドメイン検証と永続的な変更は通信アダプターではなくここに置きます。</li><li><code>crates/tiktools-client</code> に型付きラッパーを追加します。整合性テストが SDK の対応範囲と登録済み API を比較します。</li><li><code>src/web/shared/api/control-client.ts</code> 経由で利用します。Vue の entities が表示状態を持ち、デスクトップは WebView に DB やネイティブ連携オブジェクトを渡しません。</li></ol><p>Winit はイベントループ、Wry は WebView、トレイ連携はトレイを所有します。<code>HostEmitter</code> とドメインイベントが直列化した値をコアから運びます。デスクトップはイベントループプロキシを介して処理を渡し、WebView のスクリプト評価はそのスレッドで行います。非同期ホスト処理は Tokio が実行します。</p><h2 id="concrete-boundary-check" tabindex="-1">具体的な境界の確認 <a class="header-anchor" href="#concrete-boundary-check" aria-label="Permalink to &quot;具体的な境界の確認 {#concrete-boundary-check}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>最初はフロントエンドクライアントを検査します。次はロックファイルを保ったまま SDK の統合テスト対象を直接実行します。Cargo の対象フラグは狭い対象テスト構文ではなく <code>rust</code> の引き渡しを使います。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>全クライアントが同じ権威ある操作・イベント経路を観測します。<code>host --ipc</code>、<code>host --stdio</code>、<code>--standalone</code> は意図的にヘッドレスの所有権を作り、通常の CLI は既存の所有ホストへ接続します。旧 <code>PageMessage</code>/<code>IpcRouter</code> は互換コードとして残り、新しいメッセージ種別を追加すべきではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>クライアント間で食い違う場合は、別ストアを追加する前にホスト ID、ホーム、ビルド機能、検出結果を比べます。プラグイン不足は実行時カタログの問題で、コアへ実装を組み込む理由にはなりません。過去の構造文書には廃止されたフロントエンドパスがあります。異なる場合は<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/lib.rs" target="_blank" rel="noreferrer">現在のコア</a> と<a href="./frontend.html">フロントエンド構成</a> に従います。</p><p><img src="`+a+'" alt="TikTools の AppCore、通信層、ControlClient、実際の Vue ワークスペース"></p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>選択バイナリの Cargo features がコンパイル対象を決めます。コア既定は <code>native-plugins</code> と <code>napi-vm-node-api</code>、<code>persistence</code> は SQLite、<code>native-tiktok</code> は LIVE アダプターと入口、<code>plugin-install</code>・<code>cloud-auth</code>・<code>app-update</code> は各サービスを追加します。<code>cargo tree -p tiktools-desktop -e features</code>（または実際の CLI）と実行時の <code>system.info</code>・discovery を確認します。コンパイル済みでも構成済みサービスとは限りません。<a href="./performance.html">性能</a>の <code>native-tiktok</code> 回帰で LIVE 入口を明示的に検証します。</p>',16)])])}const F=t(r,[["render",c]]);export{b as __pageData,F as default};
